inline const Parameter* find(int id) {
    std::size_t first=0, last=count;
    while(first<last) {const auto mid=(first+last)/2; if(parameters[mid].id<id)first=mid+1;else last=mid;}
    return first<count && parameters[first].id==id ? &parameters[first] : nullptr;
}
inline int encode(const Parameter& p, float value, float maximum) {
    if(maximum<=p.minimum)return 0;
    const float unit=std::clamp(p.logarithmic ? std::log(std::clamp(value,p.minimum,maximum)/p.minimum)/std::log(maximum/p.minimum) : (value-p.minimum)/(maximum-p.minimum),0.0f,1.0f);
    return static_cast<int>(std::lround(unit*16383.0f));
}
inline float decode(const Parameter& p,int raw,float maximum) {
    if(maximum<=p.minimum)return p.minimum;
    raw=std::clamp(raw,0,16383);
    float value=raw==0?p.minimum:raw==16383?maximum:p.logarithmic ? p.minimum*std::exp(std::log(maximum/p.minimum)*(static_cast<float>(raw)/16383.0f)) : p.minimum+(maximum-p.minimum)*(static_cast<float>(raw)/16383.0f);
    if(p.integer)return std::round(value);
    // Preserve exact unity/default and centre values at their nearest MIDI code.
    if(p.initial>=p.minimum && p.initial<=maximum && raw==encode(p,p.initial,maximum))return p.initial;
    if(p.minimum<0 && maximum>0 && raw==encode(p,0,maximum))return 0;
    return value;
}
